#include "KS/SRC/color_shared.h"
#include "KS/SRC/stringx_shared.h"
#include "g++-2/stl_list_shared.h"

typedef float rational_t;
typedef float time_value_t;
class widget;
class wevent;
typedef list<widget *> widget_list_t;
typedef list<wevent *> wevent_list_t;
class vector2d { public: rational_t x, y; };
class rectf { public: vector2d tl, br; };

class widget
{
public:
  enum widget_type_e { WTYPE_Bitmap, WTYPE_Text, WTYPE_TextBlock, WTYPE_Vrep, WTYPE_Entity, WTYPE_Menu, WTYPE_HelpLine, WTYPE_HelpGroup, WTYPE_PDAPage, WTYPE_Other };
  enum widget_state_e { WSTATE_None, WSTATE_Show, WSTATE_Hide };
  enum rhw_layer_e { RHW0, RHW1, RHW2, RHW3, RHW4, RHW5, RHW6, RHW7, RHW8, RHW9, RHW_OVER_PFE1, RHW_OVER_PFE2, NUM_RHW_LAYERS };
  widget( const char *_widget_name, widget *_parent, short _x, short _y );
  virtual ~widget();
  virtual void show();
  virtual void hide();
  virtual void ignore_parent();
  virtual void obey_parent();
  virtual void ignore_parent_showing();
  virtual void obey_parent_showing();
  virtual void frame_advance(time_value_t);
  virtual void render();
  virtual void message_handler(unsigned int, unsigned int = 0, rational_t = 0, rational_t = 0);
  virtual void add_child(widget *);
  virtual void flush();
  virtual void move_to(short, short);
  virtual void move_to(time_value_t, time_value_t, short, short);
  virtual void scale_to(rational_t, rational_t);
  virtual void scale_to(time_value_t, time_value_t, rational_t, rational_t);
  virtual void scale_to(rational_t);
  virtual void scale_to(time_value_t, time_value_t, rational_t);
  virtual void rotate_to(rational_t);
  virtual void rotate_to(time_value_t, time_value_t, rational_t);
  virtual void set_color(color);
  virtual void set_color(color [4]);
  virtual void set_color(time_value_t, time_value_t, color);
  virtual void set_color(rational_t, rational_t, rational_t);
  virtual void fade_to(rational_t);
  virtual void fade_to(time_value_t, time_value_t, rational_t);
  virtual void set_subrect(int, int, int, int);
  virtual void set_origin(short, short);
  virtual void transform(rational_t [2], color &, int);
  virtual rational_t get_width();
  virtual rational_t get_height();
  virtual void set_layer(rhw_layer_e);
  virtual void update_pos();
  virtual void update_scale();
  virtual void update_rot();
  virtual void update_col();
  static const rational_t rhw_layer_ranges[NUM_RHW_LAYERS][2];
  static rational_t rhw_2d_val[NUM_RHW_LAYERS];
protected:
  stringx widget_name;
  widget_type_e type;
  widget *parent;
  widget_list_t children;
  unsigned int flags;
  wevent_list_t wevent_run_list;
  bool linear_animation;
  bool use_proj_matrix;
  widget_state_e next_state;
  time_value_t state_wait_time;
  short x, y, abs_x, abs_y, base_x, base_y, orig_x, orig_y;
  rational_t angle, abs_angle, base_angle;
  rational_t R[2][2];
  color col[4], abs_col[4], base_col[4];
  rational_t S[2], abs_S[2], base_S[2];
  rectf subrect;
};

widget::widget( const char *_widget_name, widget *_parent, short _x, short _y )
  : widget_name( stringx( _widget_name ) ), parent( _parent ), x( _x ), y( _y )
{
  int i;
  type = WTYPE_Other;
  flags = 0;
  linear_animation = true;
  use_proj_matrix = false;
  next_state = WSTATE_None;
  state_wait_time = 0.0f;
  base_x = 0;
  base_y = 0;
  orig_x = orig_y = 0;
  base_S[0] = base_S[1] = S[0] = S[1] = 1.0f;
  R[0][0] = R[1][1] = 1.0f;
  R[0][1] = R[1][0] = 0.0f;
  base_angle = angle = 0.0f;
  for ( i = 0; i < 4; ++i )
  {
    base_col[i].r = base_col[i].g = base_col[i].b = base_col[i].a = 1.0f;
    col[i].r = col[i].g = col[i].b = col[i].a = 1.0f;
  }
  if ( parent )
  {
    parent->add_child( this );
  }
  else
  {
    for ( i = 0; i < NUM_RHW_LAYERS; ++i )
    {
      rhw_2d_val[i] = rhw_layer_ranges[i][0];
    }
  }
  update_pos();
  update_scale();
  update_rot();
  update_col();
}
